  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (671::BIGINT, 'El curso fue completamente virtual, solo había que ver una clase grabada, realizar un resumen y hacer un quiz. El curso es muy fácil, aunque sería ideal que fuera más interactivo que solo eso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '2664289889642d27c6aa3914a6896aaa938004672b700b9ecf7eac8190a8ee6e'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'El peor profe de la carrera, no se le entiende nada. Todas las tareas hay que hacerlas en lápiz y papel.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2025-10-28T00:00:00+00:00'::TIMESTAMPTZ, '3b95caba22be20519d1a6d0a698a8ed927cee5fc74872f26ee07f2556a348880'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'El profesor es buena gente y busca que uno pase el curso. Pero al dar clases es de lo peor, no hay coherencia alguna en las explicaciones que da, hoy algo está bueno y el día de mañana está completamente erróneo. Se nota mucho el favoritismo por ciertos estudiantes y les da un trato diferenciado.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'd4f30dc7f9b083bdc09876ef8f237a1a7058c007fb26a94ea715d62b39f0091f'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'El curso es confuso, el profe como tal es muy buena persona, comprende al estudiante y busca que uno logre pasar el curso. Es decisión de cada uno si aprende o no en el proceso.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'b41c7ca81b934022762f3a31283fe39177846f9be4cbddeeecae73ca52e0c788'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'Es muy fácil pasar con este profesor, regala muchos puntos, cuando lo llevé habían dos exámenes que en conjunto eran 70% (uno de 40%) no obstante, siento que eran facilitos. No hubieron proyectos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2024-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'd65a1ffd2458d50abec12997aeb3c83cc66c08d38f9d7ee0e3fbbe114757ead1'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Lo que ya se sabe de Segreda pésimo profe, no sabe nada todo le toca al estudiante, no digo más porque me clausuran este comentario no sé como da clases este mae.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '8f8d64bdf2f03d9095e8b24c56c09eb262eab72a12c7f00a7cfc50c5922db00b'::TEXT, ARRAY[2548]::BIGINT[]),
    (671::BIGINT, 'Es un asco de profesor, no se sabe si lo que explica se lo saco del rabo o tiene fundamento pues explica lo que se acuerda, si usted no dice lo que quiere escuchar le va mal en los examenes, es un inmmaduro, narcisista que juega de joven'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-01-28T00:00:00+00:00'::TIMESTAMPTZ, '801824de06e686bb76250a7cafe7cf865c6c0d9ebc0a4d631ad0a5bbf9e782cc'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'Que asco la verdad, pesimo profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-19T00:00:00+00:00'::TIMESTAMPTZ, 'e9db780b333ca57c7be8ccb0da0ab2994811acc353cdd356487dfaa3ada05c9a'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'El peor profesor de la carrera de lejos, favoritismo, sistema de evaluación mediocre, dos clases durante todo el semestre y el resto fueron laboratorios con una pésima guía para hacerlos. Muy dificilmente se quede, pero no va a aprender absolutamente nada, será un curso para el olvido.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a1ce06fd07814c2b74763a33cb6732fbf79f19acf59dbe9c58a3ed4672702bd3'::TEXT, ARRAY[2548]::BIGINT[]),
    (671::BIGINT, 'Es un profesor que se sale de los estándares y choca con el modelo tradicional de enseñanza. Sin embargo, es el profe con más conocimiento técnico que he tenido y después de 5 cursos con él puedo decir que he aprendido muchísimo y además comprende al estudiante. En fin, super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '22cef497b626fd92679b6ac03d76e8f2eb95f4d9bef328995b60b04799f26863'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Lo mismo de siempre. Explica voladísimo y a cada rato se sale de la línea de los temas; favoritismos marcados y los criterios de evaluación son subjetivos completamente (un día un aspecto está bien, al otro día, no) PD: En arqui deja todo para el final, el curso termina un día antes de actas'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '60e4f92613d7f3bb91ee572f5514128346b70f1b2c411bb8dc8cc57ee3966b40'::TEXT, ARRAY[2518, 2548]::BIGINT[]),
    (671::BIGINT, 'Todo es grupal, con un buen grupo y pasa fácil, pero no le entendí mucho a ese bro =( Se pasa fácil o él pasa a los demás'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8cb3c654aae6a96a01ba0ccc0aed1bd4913122c223ff9c164abff107a2b35738'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'Que profe más malo, es como si se esforzara para ser cada vez peor, se nota que está improvisando y es un desorden. PD: Si creen que como profe es malo, como jefe es mucho peor.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2023-03-20T00:00:00+00:00'::TIMESTAMPTZ, '25464e06231bcdc946dd6b44f453f14664a6f9f61a087d5d60b94c5991fe1683'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Me gusto la clase. El profe explica con ejemplos y la evaluación son casos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-03-07T00:00:00+00:00'::TIMESTAMPTZ, 'b7c3b644658266a7cf16eae81aa1ae85df50b5e716181d38c2f869827e7cde57'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Segreda no sabe ser profesor, tenga por seguro que el curso lo va a pasar de fijo, pero probablemente no vaya a entender nada. Básicamente si no tiene un buen equipo de 4 personas perdió el curso, ya que todo es en grupo. Explica como él entiende, no como los demás entiendan, en fin, pésimo profe.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '2a2de98d255970a7ebeff635016c0079da6aa80e570583d04606d25b0d71208a'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'La clase es muy enredada, sus explicaciones son super rapidas y nada teoricas, los examenes son faciles, se pasa relativamente facil, participe en clase e intente caerle bien.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2022-11-28T00:00:00+00:00'::TIMESTAMPTZ, '92eec72c2ad0ef7cf3fab32a23dde60a54794f744faf9099278508e8a39d3e83'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Es todo un caso jaja, explica bien a mi gusto, porque sabe mucho y se preocupa porque uno entienda. Pero puede ser medio desordenadillo, pero nada grave,'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9d25cebcc15cd72cc24da228774c113f9bb892e6c616037418f91a5c423eab5b'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'Lo mismo de siempre, favoritismos, desordenado a más no poder, métodos de evaluación absurdos. Ojalá Isaac vuelva asap para que ya tengamos profesor :) PD: En la empresita que tiene suele no pagar salarios.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'a6a5d906bac9aa3f52a11cc1b4474aaa5df28707ecce35a44d17a3353e8a4119'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'Llegó dos horas tarde a aplicar un examen porque sí, cero compromiso y se contradice a cada rato.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e2b635a58e50a0751c49ace0f3b8e1df71c9853fdee753c0a1043e20ffdefab2'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'Al profe se le nota que desea transmitir su conocimiento hacia los estudiantes. Muchas veces en las explicaciones se desvía del tema principal. Se preocupa por que el estudiante entienda y sus evaluaciones tratan de ser simulaciones del mercado. Preguntele al realizar trabajos, como el proyecto.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '2f9ed3f05b037decbbf0b67a4236cb8c1d1fd75f29631e0cee5d84384aabae09'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Contrario a la mayoria, en este curso me pareció excelente. Clases cortas, explicaba rapido pero entendible, examenes super sencillos y en grupo. Solo hay que saber que es diferente a los demas, pero muy bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, '762cabe4b0cd27721eea3ec1ca5d56a7389b9492dc65e046968fd68facb54603'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'Las clases son confusas. Sólo hace dibujos raros para explicar toda la materia. Habla rapidísimo y se desvía constantemente del tema. Vaya apuntando TODO lo que pueda porque no suele las clases ni el material. Los exámenes son grupales y esta vez los hizo orales. Deja además, una exposición grupal'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '1e83f5b0fb32b248b7b25a3760a2fd9ca1e6fc5f7268c295d0f34805f6c6aacd'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'La evalución es un misterio, basicamente todo el curso no se sabe que diablos le está evaluando, solo se sabe que uno tiene que cumplir con todo. VAYA AL PIZZA QUIZ Y VAYA CON TODO EL GRUPO. Es mejor profe en presencial que en virtual.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes']::TEXT[], '2022-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'c4f46f2b6756a46b409d74993d5e652637f44fc029fe5350e45a7722407604b6'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'Estoy seguro que tiene problemas mentales. Puede saber mucho de la materia pero se esfuerza en ser de los peores profes de ATI. Habla en 2X, no organiza nada, no sabe ni donde está parado y cuesta entender los jeroglíficos que hace.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'e431240def8331cf99438380f74dfc2ca00647b044f854607df3c9e7fc2b12e5'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'Explica sumamente rapido, sin embargo no le molesta repetir y encontrar la forma para que se entienda. En un minuto puede decir mil cosas por lo que no hay que perder la concentración.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Pocos exámenes', 'Muchos proyectos grupales']::TEXT[], '2022-01-17T00:00:00+00:00'::TIMESTAMPTZ, '39fb366c42822a9e3d9e23ba65d936914af4fc8e8647590c551a553dd1576ea1'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Lo mismo de siempre. Desorden, improvisación, poca claridad de la materia.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Pocos exámenes']::TEXT[], '2021-08-02T00:00:00+00:00'::TIMESTAMPTZ, 'd5c5c7025ad967f350cf9f59012b64465dbefc91b3a7f7b8bba6b1ac46c54eb6'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Malo, hasta decir basta, no se aprende, desordenado, si matricula con él, puede estar seguro que no va a aprender nada. Lo peor, en la escuela se ATI no hacen nada con este "Profesor". Lo más mediocre del TEC'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-25T00:00:00+00:00'::TIMESTAMPTZ, 'd1f38b2fc719afad597f05dbf1c7a36b67d02282f196a32c0a767db4e1c52ad5'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Posiblemente el peor profe que he tenido. Desorganizado, se improvisa a última hora muchas cosas como proyectos, exámenes, etc. Estoy seguro que ni siquiera revisa las evaluaciones, por eso es fácil pasar, pero no se aprende nada con él.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '38317d8eaf9f82cceaded62c0f2e830a98ac58470d9b5c89a2c666e0ce2249d6'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'LO BUENO: deja un lab extra para ganar un poco más de puntos. LO MALO: explica muy mal, desorganizado, si pregunta puede que le responda o no. CONSEJO: grábese las clases porque las va a ocupar repasar para los labs.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'ac264e274d0830e7c0161f568b59db1116f5b97817cc052536938f3399d692ee'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'El profe es muy bueno manejando la información, pero como profe, si no logra participar y adaptarse a la clase, probablemente se lo termine llevando. Tiene que ser lo más participativo posible y así no va a entrar en su lista negra.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '4fc3418c37cb2fb8ea350fbd62502d30a782402f771879c97c9ac6e6e0343171'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Tiene mucha experiencia profesional pero como profesor es pésimo. Las explicaciones son voladísimas y no son clarar para el nivel de conocimiento de la mayoría. Para el proyecto pide cosas que nunca se vieron y no da especificaciones claras (ni siquiera un documento).'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '3309f2e0b750f03f0633458c586f1ce4c31579f263f55fe3a991feabdba373df'::TEXT, ARRAY[2541]::BIGINT[]),
    (671::BIGINT, 'Este mae, parece el gemelo de Sonia, pide varas voladas y las clases de él son malisimas, el mae en clases no graba ni nada, solo contesta a lo que le conviene y eso. La clase sume, el proyecto cree la base de datos de la NASA.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, '3e222239b376d3efd102d214d3019276cb29edaed373374dc864ab9774943b58'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Pasa que al mae solo le importa él mismo, si a usted le cuesta aunque sea un poco, va a tener que apoyarse en su grupo porque él no es nada accesible. La materia, los exámenes y labs NO van acorde con lo que se ve en clase, es todo demasiado volado.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '4650df3e15aff75a38b7a699d1a95c5f67d0439878ef9b2ac9fcea6230208b9a'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Virtual fue un dolor. explicaba VOLADISIMO y los ejemplos que daban a veces era muy pobres. Explica lo básico y en los laboratorios mete materia súper volada. Su nota depende de su grupo. Así que busque uno bueno y responsable. No deja clases grabadas y no es claro con las evaluaciones'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2020-12-20T00:00:00+00:00'::TIMESTAMPTZ, '62e787d3bdd70dff83d5a164ed37d07dbcf4db840cfb3bcb2f2914a52d19fe3d'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Cree que es perfecto y que todo lo deja claro, pero no es así. Como en el Finder tiene una "lista negra" y a los que están ahí básicamente los menosprecia y no los ayuda en nada. La materia no es fácil y se depende todo de los compañeros de equipo, en los que el profe también tiene sus favoritos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales']::TEXT[], '2020-11-18T00:00:00+00:00'::TIMESTAMPTZ, '32c516f8f639ee4830d6509b0adb7245828c893c096c7418263ec53d8eaa67b4'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Un profesor completamente basado en favoritismos, tanto en el grupo completo como individualmente, y todo esto influye en que tan dificil sea el curso y su atención, dedicación y menosprecio para con los estudiantes, las especificaciones de trabajo son sumamente pobres y mal hechas.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-31T00:00:00+00:00'::TIMESTAMPTZ, 'd28f5fa468fa9cab7e4f662444f2eff84174c2b5848756b173e684d434d207d2'::TEXT, ARRAY[2571, 2518, 2548]::BIGINT[]),
    (671::BIGINT, 'El profesor es regular. A veces no se le entiende, pero siempre está dispuesto a volver a repetir las veces que sean necesarias. Antes de los exámenes hace un "pizza quiz", ponga atención a las preguntas porque son muy parecidas a los exámenes. Todo se hace en grupo, así que busque uno bueno.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Da crédito extra']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '8d8dcd43294ba77690675d999fa18bc4ef6be15ea50e5b7b4c20a003054a8eee'::TEXT, ARRAY[2532]::BIGINT[]),
    (671::BIGINT, 'Vean, él es una persona para nada accesible, es lo que dice y se acabó no valora el tiempo de uno es extremadamente favoritista, si usted le cae bien ya pasa sino va a costar que lo atienda en consulta "obligada" y lo va a ningunear, deja unas especificaciones tan pobres que hay que buscarlo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'bbac1236c7099c4fad904bbf0bc5c2b223c9a2dd54e995b94f85735e38d41456'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Al principio se va a sentir retrasado en este curso pero luego se vuelve llevadero. No le sorprenda absolutamente nada de este profesor (eso necesariamente no es malo), la mayoria del curso es grupal y vaya a consulta al chile porque sino lo puede hacer pasar un mal rato.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-04T00:00:00+00:00'::TIMESTAMPTZ, '01f2b88fec6ad37e23ab965ac627b6c43a073980860a04623980e5b5f807901b'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Un genio en cuanto a su área, el mae sabe un montón. El problema? . El compa es sumamente desordenado y charlatán, los exámenes suelen ser super bizarros porque no hay otra palabra. Puede pasar de héroe a villano en 1 seg.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2020-01-23T00:00:00+00:00'::TIMESTAMPTZ, '5d6f8743e931dd4c792e9bcf41baf8415e7f23d40360e17bb977b08d36f19253'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2019-12-13T00:00:00+00:00'::TIMESTAMPTZ, '8f84624571a08318efef77261bada7c81e2a0ec2b5bfd860653973f9d10252ff'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Muy buen profesor. Debería de comprar su propio proyector para no perder tiempo esperando a que un alumno se lo traiga.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2019-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'a4a70395b7c8d715cb299ae5f28838b3f72aef8cbdbbaa84451cb6dd968f2466'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Excelente'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'e4d5c24d5e6c6867a35cc79488a3e3bc7307eeeabe67ba3ce5e59d76e26e5250'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Al inicio el curso se ve difícil, pero luego todo bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f6a52aa883754707913a64d079c956c174554e4df04c7c54a5de8f1489e99002'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Excelente curso, el mae está muy disponible ayudar.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-29T00:00:00+00:00'::TIMESTAMPTZ, '19d14581ee100113bb699c5df0e172f1d904cee18d76b327290dae6dad14e334'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Si el grupo le cae bien, puede ser que todo el curso sea en grupo. Durante las clases se distrae mucho y humilla al estudiante. Tiene favoritismos'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b3386156e0aa74906188a3c935ee6e5fafec0b91bd027666f29ee8de951024a9'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'El profe trata de ser parejo con todo el mundo; el problema que a veces tiene es que como que le da cosa dejar a la gente y al final pasa todo el mundo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-08T00:00:00+00:00'::TIMESTAMPTZ, '46712ba7cf52c3141e45607f3dbba45b3e1e1aca11e3704480377a726b6aa453'::TEXT, ARRAY[2571, 2577, 2589]::BIGINT[]),
    (671::BIGINT, 'Profesor totalmente subjetivo, se nota su favoritismo y eso puede llegar a perjudicar su nota final, al punto de quedarlo. No aprendí nada del curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-07T00:00:00+00:00'::TIMESTAMPTZ, '4d414ae4dfd4fe364f05bdc61d148e47c44db50bc601380bf9a73e8a64576129'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Me gustan los ejemplos que ponía en clases. En especial el de la ruta para dejar alumnos. Debería hacer más pizza quiz, realmente sirven para repasar la materia antes de 7n examen'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-14T00:00:00+00:00'::TIMESTAMPTZ, 'e994502bed2efbb7568c74f4afee75f7150c8a8e33b32579db0d5eb04275bbac'::TEXT, ARRAY[2534]::BIGINT[]),
    (671::BIGINT, 'Es un buen profe, a veces sus clases son muy largas y mucha teoría. Pero se esfuerza y siempre dispuesto a atender dudas, incluso fuera de clases.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-06T00:00:00+00:00'::TIMESTAMPTZ, '2394f984a8cbd22f8d1389aea05f6db68fcda483406b6efa37e8d86ba47c6aa7'::TEXT, ARRAY[2577, 2589]::BIGINT[]),
    (671::BIGINT, 'El mejor profe, se interesa en los alumnos y hace actividades. Es una lastima que no no de infra 2. :''('::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-09-07T00:00:00+00:00'::TIMESTAMPTZ, '2229c2c77cc96d3d87e506b00c106fc47bf172d16430c3c23a253fd75bd62954'::TEXT, ARRAY[2534]::BIGINT[]),
    (671::BIGINT, 'El peor profe de ATI sin duda, en OAC como no le gusta dar ese curso entonces le da igual todo. No se le entiende nada y tiene demasiado favoritismo. Si usted le cae bien ya pasó'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2019-08-28T00:00:00+00:00'::TIMESTAMPTZ, '01a41de2886566ba64e61816496a445df1e6be1216da2b2d93eb063a221e1cd7'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Marca demasiado el favoritismo, no se entiende nada de lo que intenta explicar. Muy desordenado'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '9d72608231dd3a4133c790e82d53fe5df7fd28df18ee111d28910e123f928114'::TEXT, ARRAY[2543, 2534]::BIGINT[]),
    (671::BIGINT, 'Es un charlatán, no explica nada claro, muy desordenado, casi nadie aprende nada porque sus metodologías son birzarras y poco convenientes. Los examenes son un asco ya que son parte escrita-oral y subjetivos. Marca demasiado el favoritismo. Buena persona pero el peor profesor que he tenido.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa']::TEXT[], '2019-05-04T00:00:00+00:00'::TIMESTAMPTZ, 'ca0ca95422a0a673c1f14efd4cd5d6c6011ff13ea71477b376ac81c3b559a69c'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'El peor profesor que tiene ATI , no se pone en duda su conocimiento en el campo sino la forma de dar clases. Le encanta hacerse amigo de los alumnos (charlatán), dura mucho haciendo quices, desordenado y prácticamente quiere que el asistente le lleve el control de todo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-10T00:00:00+00:00'::TIMESTAMPTZ, '6385cd72197b2f4f31746d1843011e14a5fc688a82c3cbb9dfdaa94d6ee82d43'::TEXT, ARRAY[2534, 2543, 2571]::BIGINT[]),
    (671::BIGINT, 'Es un poco desordenado, pero sabe mucho e intenta que aprendamos'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3bfc03ed6f6c3efa8bd526a4fe1055348359034bcdcf8523bca6527f92d8cfe4'::TEXT, ARRAY[2589, 2577]::BIGINT[]),
    (671::BIGINT, 'Es buen profesor, pero siempre llegaba tarde. Hay que participar bastante y a la hora de explicar no se le entiende mucho. Los exámenes y quices los califica muy subjetiva mente y hay que caerle bien.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'e1033c5b20263e9387f01c2f5106eca3ee75ba831818de08044622854f69ae23'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'El profe sabe mucho y ayuda. Es parejo con todo el mundo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'ece3aff167929703bac9b8e378d9e5111222f5b1bea004f2b5d0be3a50de0901'::TEXT, ARRAY[2543]::BIGINT[]),
    (671::BIGINT, 'Profe muy desorganizado, pretende explicar materia nueva faltando 5 minutos para terminar la clase, sabe mucho pero no sabe cómo explicar. Marca mucho el favoritismo. Si le caes bien, pasas.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'e80bf159d8929998a063d143a18f4cf148946246015db3c058e8143031fe3eab'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'Conoce la materia pero no es buen profesor, tiene muchos favoritismos por ciertos estudiantes y por cualquier comentario negativo brinca y en el siguiente examen se desquita, tiene metodos de evaluacion sumamente dudosos pero si participa y le cae bien se pasa el curso'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'La participación importa', 'Exámenes retadores']::TEXT[], '2018-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'd12df653a126a4ce056233635d5ab077c0a34601be78e4f39c9caa71d4475ac3'::TEXT, ARRAY[2543, 2534]::BIGINT[]),
    (671::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-08T00:00:00+00:00'::TIMESTAMPTZ, '87cf2f21bbac647ea4d968f7035b549855533a8e6f5d1c6f252e7d95689aafa6'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Profesor que sabe del tema, desorganizado y lleno e favoritismos con algunos estudiantes. No es el tipo de profesor con el que llevaría otro curso. Usa diapositivas que el contenido uno lo puede sacar fácilmente de internet.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-14T00:00:00+00:00'::TIMESTAMPTZ, '0251c0f2f184a99ae40926a7f3d95ab3aa16743e14bb80f7b74d32a46d1bc87a'::TEXT, ARRAY[2543]::BIGINT[]),
    (671::BIGINT, 'Buen profe, a veces se le olvida que no todos tienen el mismo nivel de conocimiento. Preparese para metodos de evaluación un poco bizarros. Estudie para los quizes que son todas las semenas, participe bastante, no falte y pasa el curso fácil.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales']::TEXT[], '2017-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'c8b1d98ffa43ee4fc50b9d31b8512ebcd3239f7c93f46061a5cbb4c6a01fc1b6'::TEXT, ARRAY[2518]::BIGINT[]),
    (671::BIGINT, 'No dudo que sea una persona que conozca mucho de la materia que esta dando a sus alumnos, porque sabe mucho y no es un mal profesor, pero debe ser mas neutral y dejar los favoritismos de un lado. Sus cursos son pasables.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b41a8b4ace29c8f2499fe82369de4e6ee703266bbae60e9b52ad9ff021a978de'::TEXT, ARRAY[2534, 2543, 2571]::BIGINT[]),
    (671::BIGINT, 'Las evaluaciones con él son muy diferentes y divertidas, el curso en sí es muy teórico es demasiada materia, pero él le da su toque personal para que sea relajado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c5db7d46f101952b902c085634982a2735980ed8b38fc96591cace3107a778af'::TEXT, ARRAY[2534]::BIGINT[]),
    (671::BIGINT, 'el profe es bueno, el curso seria sumamente mejor si se hicieran casos completos durante todo el semestre y no solo 2 al final y medio explicados.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '19ca98f1f19366efd515a3172b5316e7302bc0b68c4dd89666153414fa4e5046'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'El profe es crack, el problema es que a veces se vuelve sumamente teorico, pero esos cursos son de ese estilo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-12T00:00:00+00:00'::TIMESTAMPTZ, '7b80f12dedd0f16a25aab37b7bd733ac6968c1329b9c0dd24dad1c2c765612bb'::TEXT, ARRAY[2589]::BIGINT[]),
    (671::BIGINT, 'Mis respetos para el profe, super crack sobre cualquier cosa que tenga que ver del hardware de equipos electronicos, ademas conocer con Star Wars y los examenes son duros pero el mae motiva a que la gente salga bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '45e40c0981fbcfc23317ddebc04ce89dfe50b399533f338d2855d58bf77957e2'::TEXT, ARRAY[2534]::BIGINT[]),
    (671::BIGINT, 'Muy buen profesor, tiene mucho conocimiento sobre los temas que da en clase, se interesa más por el aprendizaje del estudiante que de sus notas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'b9b8944d78181b62133dc0bba2fe73f9a11a0e800dd84875294bad3ac978ad9b'::TEXT, ARRAY[2571]::BIGINT[]),
    (671::BIGINT, 'Excelente profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-19T00:00:00+00:00'::TIMESTAMPTZ, '3820b14e7706ee49b28b1d5eb43eff81ed144de5a1e99eb97bc35ae002f9efd0'::TEXT, ARRAY[2534]::BIGINT[]),
    (671::BIGINT, 'Excelente profesor! Ayuda mucho, atiende dudas fuera de clases y le preocupa que el estudiante aprenda.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '5147409207fb04938b851503187c55e8b0a9fdd805f4cbd59909fb39d45dbe29'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'Desorganizado, nunca planifica la clase, explica a medias y pretende que todos sepan.Dem choteador cuando le preguntan y en general, es burlista con quien pregunta algo o no sabe. En taller no explica nada.Califica muy suave, pero no lo recomendaría a nadie, si no quiere llegar perdido al sig curso.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'f3c5b3cf74654fc63d26b0a215e9116d66a686c06b398ad4b27430bac302db8b'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'Recomendado!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '46825fbe91b3eef1a627fc74e536297cce436d10b899c767d2df00cfb1cbc1f9'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'Simplemente el mejor profe. UNi aprende y no solo como programar sino como hacerlo bien y eficiente'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e6579ccc2ad3292eebca6880d59526f76371c3b817346036f5c6bb46e2d5030a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'Si usted anda buscando un curso para pasarlo cagado de risa aqui no lo va a encontrar. Sin embargo si su meta es ser uno de los mejores en su campo recomendadisimo que lleve el curso con este mae! Él da el curso más duro que otros maes, pero el ambiente es super tranquilo y uno sale mejor preparado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '2b9cf057a69bd1d447d6f22ce99277558bd95a741b126619d812a65edb95a993'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'Excelente profesor, le importa mucho q los alumnos aprendan. Cuando revisaba los examenes nos daba la retroalimentacion para mejorar.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '5b7017c714f84f182e9c376ec4a9869ad29a9eadf737960ae195944d4bfebf5a'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'Muy buena opción'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '785ac2010bc1975516c2ee20046d237c5dce9de5fd67606c3d7f51b4948c4f23'::TEXT, ARRAY[2510]::BIGINT[]),
    (671::BIGINT, 'El profesor es excelente, ayuda bastante, califica los exámenes con e estudiante por lo que uno sale sabiendo la nota, ademas el nivel de nosotros es mejor que el del resto de los grupos, pero nosotros entendemos mejor; de hecho yo y varios de mis compañeros ayudábamos a varios de otros grupos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'cdb416dfd1b2617ff64fea31d580686ce00705673d40cbd2a28becc61ebd16fc'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'Excelente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '56c4e19bb09719f950f1a31b91c618d3cc1a908e8cd1dd053706d779376cdbdf'::TEXT, ARRAY[2510]::BIGINT[]),
    (671::BIGINT, 'El mejor profesor que he tenido en toda mi carrera ademas de ser un fuking genio y estar chiflado es una de las mejores personas que conozco , las clases sumamente dinámicas cero aburridas se aprende de todo y cada conocimiento que te deja es super útil en la calle , de verdad un valuarte del tec'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-10T00:00:00+00:00'::TIMESTAMPTZ, '749cd0cfcd6296c6795283f70c7ca28f6c63ed2d90d25d669d0fda7c812664a2'::TEXT, ARRAY[2543]::BIGINT[]),
    (671::BIGINT, 'Si sos de los que quieren un clase magistral de progra y que todo sea con presentaciones y eso este no es de esos, él te explica de su conocimiento y así con todos los temas trata que te esforcés en aprender y que llegués a la solución, no te enseña a programar, te enseña a pensar soluciones (Y)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'c742aa14a7153db752a15b8ca7988e3b42b2870d5064af67dc9e5b626208d2f1'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'excelente profesor, pide mucho de los estudiantes, pero ayuda demasiado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, '247ddfc1e2736556969d7e14bea62cbca807cc6d77955b4f59f53467e06ea0be'::TEXT, ARRAY[2510]::BIGINT[]),
    (671::BIGINT, 'Demaciado tuanis estar con este mae no es duro y el mae es un vasilon RECOMENDADISIMO'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '525c6749b0ef4170dbeb9cfeb8d4df42e89c45a5865126aaf6f24432d70a4382'::TEXT, ARRAY[2510, 2512]::BIGINT[]),
    (671::BIGINT, 'El profe es una teja, se aprende muchísimo y las clases son entretenidas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, '59e94839951be64b10661d887133e10ffa3bbd61dabc31b9d058bb7656ea5a69'::TEXT, ARRAY[2543]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
